// Written with the help of Claude
// AI Usage Note: generated by Claude; every case checked against the saved ArtWizard pages by running the tests.
import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import {
  ArtWizardEventProvider,
  type ArtWizardRecord,
  quillText,
} from '../../dist/infra/providers/artwizard-event-provider.js';
import type { ImportedEvent } from '../../dist/core/import/types/import.js';
import { PAGES_SAVED_AT, savedPage, savedPagesClient } from './fixtures/provider-pages.ts';

const EVENT_PATH = '/kyiv/e/vaga-ne-problema--20261111';
const EVENT_URL = `https://artwizard.io${EVENT_PATH}`;

/** The saved sitemap, the saved event page under its own path, and the error page for every other event. */
function makeProvider(routes: Parameters<typeof savedPagesClient>[0] = {}, now = PAGES_SAVED_AT) {
  const http = savedPagesClient({
    '/sitemaps/events.xml': 'artwizard/events-sitemap.xml',
    [EVENT_PATH]: 'artwizard/event.html',
    '/kyiv/e/chomu-nam-varto-buti-merkantilnimi--20261108': 'artwizard/event-error.html',
    ...routes,
  });
  return { provider: new ArtWizardEventProvider({ http, now: () => now }), http };
}

/** The record `fetch` makes of the saved event page. */
async function savedRecord(): Promise<Extract<ArtWizardRecord, { event: unknown }>> {
  const records = await makeProvider().provider.fetch();
  const record = records.find((record) => record.url === EVENT_URL);
  assert.ok(record && 'event' in record);
  return record;
}

/** The saved record with fields of its Event JSON-LD replaced. */
async function withEvent(changes: Record<string, unknown>, types?: string[]): Promise<ArtWizardRecord> {
  const record = await savedRecord();
  return { ...record, event: { ...record.event, ...changes }, types: types ?? record.types };
}

function normalized(provider: ArtWizardEventProvider, record: ArtWizardRecord): ImportedEvent {
  const result = provider.normalize(record);
  assert.ok('event' in result, JSON.stringify(result));
  return result.event;
}

// FR-008, FR-015
describe('ArtWizardEventProvider.fetch', () => {
  test('requests the Kyiv event pages of the sitemap that fall in the catalog window, and nothing else', async () => {
    const { provider, http } = makeProvider();

    const records = await provider.fetch();

    assert.equal(records.length, 8);
    assert.equal(http.requested[0], 'https://artwizard.io/sitemaps/events.xml');
    assert.ok(http.requested.slice(1).every((url) => url.startsWith('https://artwizard.io/kyiv/e/')));
    assert.ok(http.requested.every((url) => !/\/api\/|\/cdn-cgi\//.test(url)));
  });

  test('leaves out the pages dated after the catalog window', async () => {
    // On 13 October the window ends on 10 November: 7–10 November are in, 11 and 13 November are out.
    const { provider } = makeProvider({}, new Date('2026-10-13T10:00:00Z'));

    const records = await provider.fetch();

    assert.deepEqual(records.map((record) => record.url.slice(-8)).sort(), [
      '20261107',
      '20261107',
      '20261108',
      '20261108',
      '20261109',
      '20261110',
    ]);
  });

  test('keeps a page that could not be fetched as a record with the reason, and fetches the rest', async () => {
    const { provider } = makeProvider({ [EVENT_PATH]: new Error('socket hang up') });

    const records = await provider.fetch();

    assert.equal(records.length, 8);
    assert.deepEqual(
      records.find((record) => record.url === EVENT_URL),
      { url: EVENT_URL, error: 'The page could not be fetched: socket hang up' },
    );
  });

  test('fails the run when the sitemap cannot be read', async () => {
    const { provider } = makeProvider({ '/sitemaps/events.xml': { status: 503 } });

    await assert.rejects(provider.fetch(), /answered 503/);
  });
});

describe('ArtWizardEventProvider.normalize', () => {
  test('maps the saved event page to an event', async () => {
    const { provider } = makeProvider();

    const event = normalized(provider, await savedRecord());

    assert.deepEqual(
      { ...event, description: event.description.slice(0, 64) },
      {
        externalId: 'vaga-ne-problema--20261111',
        title: 'Вага (не) проблема?',
        description: 'Чи справді вага залежить лише від того, скільки ми їмо й рухаємо',
        categoryName: 'Talks',
        venue: {
          name: 'Сенс на Хрещатику',
          address: 'вул. Хрещатик, 34, Київ',
          location: { lat: 50.4470923, lng: 30.521552117 },
        },
        startsAt: '2026-11-11T17:00:00.000Z',
        endsAt: '2026-11-11T21:59:59.999Z',
        imageUrl:
          'https://artwizard.io/cdn-cgi/imagedelivery/nEFkEwcLfsgJlYjxGEgkpQ/11552fa9-b173-48e8-3471-423c8ccf9900/public',
        sourceUrl: EVENT_URL,
      },
    );
  });

  test('joins the inserts of the Quill description into plain text', async () => {
    const { provider } = makeProvider();

    const { description } = normalized(provider, await savedRecord());

    assert.ok(!description.includes('"insert"'));
    assert.match(description, /^Чи справді вага.*\n\nЗапрошуємо на зустріч з Олесею Добрянською/s);
  });

  test('takes a description that is not Quill JSON as plain text', () => {
    assert.equal(quillText('Just text, [not JSON'), 'Just text, [not JSON');
    assert.equal(quillText('[{"insert":"One "},{"insert":{"image":"x"}},{"insert":"two"}]'), 'One two');
  });

  const times = [
    { title: 'in winter (UTC+2)', startDate: '2026-11-11T19:00:00.000Z', startsAt: '2026-11-11T17:00:00.000Z' },
    { title: 'in summer (UTC+3)', startDate: '2026-07-11T19:00:00.000Z', startsAt: '2026-07-11T16:00:00.000Z' },
  ];
  for (const { title, startDate, startsAt } of times) {
    test(`reads the time marked Z as Kyiv wall-clock time ${title}`, async () => {
      const { provider } = makeProvider();

      const event = normalized(provider, await withEvent({ startDate, endDate: '2026-07-11T21:30:00.000Z' }));

      assert.equal(event.startsAt, startsAt);
    });
  }

  test('skips an event that starts at 00:00, which ArtWizard shows when the organizer gave no time', async () => {
    const { provider } = makeProvider();

    const result = provider.normalize(
      await withEvent({ startDate: '2026-11-03T00:00:00.000Z', endDate: '2026-11-03T00:00:00.000Z' }),
    );

    assert.deepEqual(result, {
      skip: { externalId: 'vaga-ne-problema--20261111', reason: 'No start time (00:00 on ArtWizard)' },
    });
  });

  test('keeps an event that starts a minute after midnight', async () => {
    const { provider } = makeProvider();

    const event = normalized(provider, await withEvent({ startDate: '2026-11-11T00:01:00.000Z' }));

    assert.equal(event.startsAt, '2026-11-10T22:01:00.000Z');
  });

  test('keeps a real end, read as Kyiv time', async () => {
    const { provider } = makeProvider();

    const event = normalized(provider, await withEvent({ endDate: '2026-11-11T21:30:00.000Z' }));

    assert.equal(event.endsAt, '2026-11-11T19:30:00.000Z');
  });

  test('ends the event at the end of its Kyiv day when endDate equals startDate', async () => {
    const { provider } = makeProvider();

    const event = normalized(provider, await withEvent({ endDate: '2026-11-11T19:00:00.000Z' }));

    assert.equal(event.endsAt, '2026-11-11T21:59:59.999Z');
  });

  test('gives no coordinates for a venue without geo, so the import looks them up', async () => {
    const { provider } = makeProvider();
    const { event } = await savedRecord();
    const { geo: _geo, ...location } = event.location as Record<string, unknown>;

    const result = normalized(provider, await withEvent({ location }));

    assert.equal(result.venue.location, null);
    assert.equal(result.venue.address, 'вул. Хрещатик, 34, Київ');
  });

  test('finds the type tags when the tags next to them are objects', async () => {
    // As on the page of "Оргія" (orgiia-20261111): an age tag carries its own slug before the event's.
    const page = savedPage('artwizard/event.html').replace(
      '\\"tags\\":[]',
      '\\"tags\\":[{\\"_id\\":\\"651c3d09\\",\\"name\\":\\"16+\\",\\"slug\\":\\"16\\"}]',
    );
    assert.notEqual(page, savedPage('artwizard/event.html'));
    const { provider } = makeProvider({ [EVENT_PATH]: { status: 200, text: page } });

    const record = (await provider.fetch()).find((record) => record.url === EVENT_URL);

    assert.deepEqual(record && 'types' in record && record.types, ['Дискусії та лекції', 'Література']);
  });

  test('takes the first type tag that has a category', async () => {
    const { provider } = makeProvider();

    const event = normalized(provider, await withEvent({}, ['Дітям', 'Кіно', 'Музика']));

    assert.equal(event.categoryName, 'Cinema');
  });

  test('skips an event whose type tags have no category, with the tags in the reason', async () => {
    const { provider } = makeProvider();

    assert.deepEqual(provider.normalize(await withEvent({}, ['Дітям', 'Інше'])), {
      skip: { externalId: 'vaga-ne-problema--20261111', reason: 'No category for the types ["Дітям","Інше"]' },
    });
  });

  test('takes no category from a tag that names an object property', async () => {
    const { provider } = makeProvider();

    const result = provider.normalize(await withEvent({}, ['constructor', 'toString']));

    assert.ok('skip' in result);
  });

  test('skips the Next.js error page the site returns for a page it cannot render', async () => {
    const { provider } = makeProvider();
    const records = await provider.fetch();
    const errorPage = records.find((record) => record.url.endsWith('chomu-nam-varto-buti-merkantilnimi--20261108'));
    assert.ok(errorPage);

    assert.deepEqual(provider.normalize(errorPage), {
      skip: {
        externalId: 'chomu-nam-varto-buti-merkantilnimi--20261108',
        reason: 'The site could not render the page (Next.js error page)',
      },
    });
  });

  test('skips a page without an Event block', async () => {
    const { provider } = makeProvider();

    assert.deepEqual(provider.normalize({ url: EVENT_URL, event: null, types: [] }), {
      skip: { externalId: 'vaga-ne-problema--20261111', reason: 'The page has no Event JSON-LD' },
    });
  });

  test('skips an event without a start, naming the field', async () => {
    const { provider } = makeProvider();

    const result = provider.normalize(await withEvent({ startDate: undefined }));

    assert.deepEqual(result, {
      skip: { externalId: 'vaga-ne-problema--20261111', reason: 'Invalid record: startDate' },
    });
  });
});
